import React ,{useState} from "react";
import { useDispatch, useSelector } from "react-redux";
import { markComplete, deleteTask } from "../State/action-creators/index";
import icon from "./assets/icons8-multiply-24.png";
import "../Style/DisplayAllTasks.css";

function DisplayAllTasks() {
  const dispatch = useDispatch();
  const tasks = useSelector((state) => state.tasks);
const [searchCategory,setSearchCategory] =useState('');
const [searchPriorty,setSearchPriorty] =useState('');
  return (
    
    <>
    <div className='SearchLists'>
    <form className='Category'>
      <select value={searchCategory} onChange={(e) => setSearchCategory(e.target.value)} placeholder='By category'>
        <option value="Learning/working">Learning/working</option>
        <option value="Playing">Playing</option>
        <option value="eating">eating</option>
      </select>
    </form>
     <form className='Priorty'>
      <select value={searchPriorty} onChange={(e) => setSearchPriorty(e.target.value)} placeholder='By priorty'>
        <option value="Low">Low</option>
        <option value="Mid">Mid</option>
        <option value="High">High</option>
      </select>
    </form>
  </div>
        <div className="task-list">
        
      {tasks.length === 0 ? (
        <ul>
          <li>No tasks yet!</li>
        </ul>
      ) : (
        tasks.map((task) => (
          <div
            key={task.id}
            className={`task-item ${!task.inProgress ? "completed" : ""}`}
          >
            <input
              type="checkbox"
              checked={!task.inProgress}
              onChange={() => dispatch(markComplete(task.id))}
            />
            <h2>{task.title}</h2>
            <span>{task.description}</span>
            <img
              src={icon}
              alt="Delete"
              onClick={() => dispatch(deleteTask(task.id))}
            />
          </div>
        ))
      )}
    </div>
    </>
  );
}

export default DisplayAllTasks;
